# so the hunter engages healthy like the top teams; adjacent hits and reach attacks are unchanged.
# params: HUNT_R=3 REACH=1 BAG_SAFE=25 BAG_NEAR=25 RET=0.3 CHASE_DASH=1 LS=0 STUN_FIRST=0 ALLY_MIN=0 PREY_HP=1.01 CHASE=1 SHIELD_HP=1.01 K10=0 TARGET=nearest ENGAGE_HP=0.8 ODDS=9

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# engage u: hit it if in reach, else close in (dash when farther than our reach), then hit
def hunt(u):
    set_team_target(u)
    if distance( unit_position(u), position() ) <= 1:
        if ability_ready(0):
            if slot_is_shield(0) or slot_is_heal(0):
                if health() < 1.01 * max_health():
                    cast_self(0)
            elif slot_is_dash(0):
                if i_am(champ_heart_of_ruin()):
                    dash_towards(0, unit_position(u))
            elif slot_is_aoe(0):
                cast_at_tile(0, unit_position(u))
            elif not slot_is_reset(0):
                cast_at_unit(0, u)
        if ability_ready(1):
